    static final int PS = 0, FA = 1, EN = 2, UR = 3, AR = 4;

    static int lang = PS;

    private L() {}

    static void init(Context c) {
        lang = Prefs.lang(c);
        Theme.load(c);
    }

    static boolean rtl() {
        return lang != EN;
    }

    static String t(String key) {
        String[] v = M.get(key);
        return v == null ? key : v[lang];
    }

    static String f(String key, Object... args) {
        return String.format(t(key), args);
    }

    /** A number written with this language's digits. */
    static String num(int n) {
        String s = String.valueOf(n);
        if (lang == EN) return s;
        char zero = lang == AR ? '٠' : '۰';
        StringBuilder b = new StringBuilder();
        for (char ch : s.toCharArray()) b.append(ch >= '0' && ch <= '9' ? (char) (zero + (ch - '0')) : ch);
        return b.toString();
    }

    private static final HashMap<String, String[]> M = new HashMap<>();

    private static void p(String k, String ps, String fa, String en, String ur, String ar) {
        M.put(k, new String[]{ps, fa, en, ur, ar});
    }

